// Filler styling, reused across the examples below. `band` outlines
// the space each Container was given, so its bounds are visible.
const panel = { p: 2, borderRadius: 1, bgcolor: 'action.hover', textAlign: 'center' };
const band = { borderRadius: 1, border: '1px dashed', borderColor: 'text.disabled' };

<Box sx={band}>
  <Container maxWidth="sm">
    <Box sx={panel}>maxWidth=sm — 600px, then centred</Box>
  </Container>
</Box>

const [sort, setSort] = React.useState("name");

<Menu anchorEl={anchorEl} open={Boolean(anchorEl)} onClose={close}>
  {["name", "date", "size"].map((option) => (
    <MenuItem
      key={option}
      selected={option === sort}
      onClick={() => {
        setSort(option);
        close();
      }}
    >
      {option}
    </MenuItem>
  ))}
</Menu>

import InputAdornment from '@mui/material/InputAdornment';
import { MagnifyingGlass } from '@neoflo/atoms/icons';

<TextField
  label="Search"
  placeholder="Search anything"
  startAdornment={
    <InputAdornment position="start">
      <MagnifyingGlass size={16} />
    </InputAdornment>
  }
/>

import { X } from '@neoflo/atoms/icons';

<TextField
  label="Search"
  endAdornment={
    <IconButton appearance="text" size="sm" aria-label="Clear" onClick={handleClear}>
      <X />
    </IconButton>
  }
/>

import InputAdornment from '@mui/material/InputAdornment';
import { Eye, Lock } from '@neoflo/atoms/icons';

<TextField
  label="Password"
  placeholder="Enter password"
  startAdornment={
    <InputAdornment position="start">
      <Lock size={16} />
    </InputAdornment>
  }
  endAdornment={
    <IconButton appearance="text" size="sm" aria-label="Show password" onClick={handleToggleVisibility}>
      <Eye />
    </IconButton>
  }
/>
